1	const { rate_limiter } = require('./rate_limiter');
2	
3	// ── Helpers ──────────────────────────────────────────────────────────
4	let passed = 0;
5	let failed = 0;
6	
7	function assert(condition, desc) {
8	  if (condition) {
9	    passed++;
10	    console.log(`  ✓ ${desc}`);
11	  } else {
12	    failed++;
13	    console.error(`  ✗ ${desc}`);
14	  }
15	}
16	
17	function assertEqual(actual, expected, desc) {
18	  const ok = Object.is(actual, expected);
19	  assert(ok, ok ? desc : `${desc} — expected ${expected}, got ${actual}`);
20	}
21	
22	function assertApprox(actual, expected, desc, eps = 1e-9) {
23	  const ok = Math.abs(actual - expected) < eps;
24	  assert(ok, ok ? desc : `${desc} — expected ~${expected}, got ${actual}`);
25	}
26	
27	function assertThrows(fn, expectedMsg, desc) {
28	  try {
29	    fn();
30	    failed++;
31	    console.error(`  ✗ ${desc} — expected error but none thrown`);
32	  } catch (e) {
33	    const ok = e.message.includes(expectedMsg);
34	    if (ok) {
35	      passed++;
36	      console.log(`  ✓ ${desc}`);
37	    } else {
38	      failed++;
39	      console.error(`  ✗ ${desc} — expected "${expectedMsg}", got "${e.message}"`);
40	    }
41	  }
42	}
43	
44	// ── Basic arithmetic ─────────────────────────────────────────────────
45	
46	console.log('\n=== Addition ===');
47	assertEqual(rate_limiter('3 4 +'), 7, '3 4 + = 7');
48	assertEqual(rate_limiter('0 0 +'), 0, '0 0 + = 0');
49	assertEqual(rate_limiter('-3 5 +'), 2, '-3 5 + = 2');
50	assertEqual(rate_limiter('-4 -6 +'), -10, '-4 -6 + = -10');
51	
52	console.log('\n=== Subtraction ===');
53	assertEqual(rate_limiter('10 3 -'), 7, '10 3 - = 7');
54	assertEqual(rate_limiter('3 10 -'), -7, '3 10 - = -7');
55	assertEqual(rate_limiter('5 5 -'), 0, '5 5 - = 0');
56	
57	console.log('\n=== Multiplication ===');
58	assertEqual(rate_limiter('3 4 *'), 12, '3 4 * = 12');
59	assertEqual(rate_limiter('0 99 *'), 0, '0 99 * = 0');
60	assertEqual(rate_limiter('-3 4 *'), -12, '-3 4 * = -12');
61	assertEqual(rate_limiter('-2 -5 *'), 10, '-2 -5 * = 10');
62	
63	console.log('\n=== Division ===');
64	assertEqual(rate_limiter('12 4 /'), 3, '12 4 / = 3');
65	assertEqual(rate_limiter('7 2 /'), 3.5, '7 2 / = 3.5');
66	assertApprox(rate_limiter('1 3 /'), 0.333333333, '1 3 / ≈ 0.333');
67	assertEqual(rate_limiter('0 5 /'), 0, '0 5 / = 0');
68	
69	console.log('\n=== Exponentiation ===');
70	assertEqual(rate_limiter('2 10 **'), 1024, '2 10 ** = 1024');
71	assertEqual(rate_limiter('5 0 **'), 1, '5 0 ** = 1');
72	assertEqual(rate_limiter('9 0.5 **'), 3, '9 0.5 ** = 3');
73	
74	console.log('\n=== Modulo ===');
75	assertEqual(rate_limiter('10 3 %'), 1, '10 3 % = 1');
76	assertEqual(rate_limiter('7 7 %'), 0, '7 7 % = 0');
77	assertEqual(rate_limiter('5 2 %'), 1, '5 2 % = 1');
78	
79	// ── Compound expressions ─────────────────────────────────────────────
80	
81	console.log('\n=== Compound expressions ===');
82	assertEqual(rate_limiter('3 4 + 2 *'), 14, '(3+4)*2 = 14');
83	assertEqual(rate_limiter('5 1 2 + 4 * + 3 -'), 14, '5+((1+2)*4)-3 = 14');
84	assertEqual(rate_limiter('2 3 + 4 5 - *'), -5, '(2+3)*(4-5) = -5');
85	assertEqual(rate_limiter('15 7 1 1 + - / 3 * 2 1 1 + + -'), 5, 'complex RPN = 5');
86	assertEqual(rate_limiter('4 2 / 3 + 5 *'), 25, '(4/2+3)*5 = 25');
87	assertApprox(rate_limiter('3 2 ** 4 2 ** + 5 /'), 5, '(3^2 + 4^2) / 5 = 5');
88	
89	// ── Single operand ───────────────────────────────────────────────────
90	
91	console.log('\n=== Single operand ===');
92	assertEqual(rate_limiter('42'), 42, 'single number returns itself');
93	assertEqual(rate_limiter('0'), 0, 'single zero');
94	assertEqual(rate_limiter('-7'), -7, 'single negative');
95	
96	// ── Floating point ───────────────────────────────────────────────────
97	
98	console.log('\n=== Floating point ===');
99	assertApprox(rate_limiter('3.14 2 +'), 5.14, '3.14 + 2 = 5.14');
100	assertApprox(rate_limiter('1.5 2.5 *'), 3.75, '1.5 * 2.5 = 3.75');
101	
102	// ── Negative numbers ─────────────────────────────────────────────────
103	
104	console.log('\n=== Negative numbers ===');
105	assertEqual(rate_limiter('-3 -4 +'), -7, '-3 + -4 = -7');
106	assertEqual(rate_limiter('-2 3 *'), -6, '-2 * 3 = -6');
107	assertEqual(rate_limiter('10 -2 /'), -5, '10 / -2 = -5');
108	
109	// ── Large numbers ────────────────────────────────────────────────────
110	
111	console.log('\n=== Large numbers ===');
112	assertEqual(rate_limiter('1000000 1000000 *'), 1e12, '1M * 1M = 1T');
113	assertEqual(rate_limiter('2 50 **'), 2 ** 50, '2^50');
114	
115	// ── Error cases ──────────────────────────────────────────────────────
116	
117	console.log('\n=== Error: empty expression ===');
118	assertThrows(() => rate_limiter(''), 'Expression is empty', 'empty string throws');
119	assertThrows(() => rate_limiter('   '), 'Expression is empty', 'whitespace-only throws');
120	
121	console.log('\n=== Error: invalid tokens ===');
122	assertThrows(() => rate_limiter('a b +'), "Invalid token: 'a'", 'non-numeric token throws');
123	assertThrows(() => rate_limiter('3 abc +'), "Invalid token: 'abc'", 'mixed valid/invalid throws');
124	
125	console.log('\n=== Error: insufficient operands ===');
126	assertThrows(() => rate_limiter('3 +'), "Insufficient operands for operator '+'", 'single operand for binary op');
127	assertThrows(() => rate_limiter('+'), "Insufficient operands for operator '+'", 'only operator, no operands');
128	
129	console.log('\n=== Error: too many operands ===');
130	assertThrows(() => rate_limiter('3 4 5'), 'too many operands', 'three numbers, no operator');
131	assertThrows(() => rate_limiter('1 2 + 3'), 'too many operands', 'expression with leftover');
132	
133	console.log('\n=== Error: division by zero ===');
134	assertThrows(() => rate_limiter('5 0 /'), 'Division by zero', '5 / 0 throws');
135	assertThrows(() => rate_limiter('0 0 /'), 'Division by zero', '0 / 0 throws');
136	
137	console.log('\n=== Error: wrong type ===');
138	assertThrows(() => rate_limiter(123), 'Expression must be a string', 'number input throws');
139	assertThrows(() => rate_limiter(null), 'Expression must be a string', 'null input throws');
140	assertThrows(() => rate_limiter(undefined), 'Expression must be a string', 'undefined input throws');
141	
142	// ── Whitespace handling ──────────────────────────────────────────────
143	
144	console.log('\n=== Whitespace handling ===');
145	assertEqual(rate_limiter('  3   4  +  '), 7, 'extra whitespace is tolerated');
146	assertEqual(rate_limiter('3\t4\t+'), 7, 'tab-separated tokens work');
147	
148	// ── Summary ──────────────────────────────────────────────────────────
149	console.log(`\n${'='.repeat(50)}`);
150	console.log(`Results: ${passed} passed, ${failed} failed, ${passed + failed} total`);
151	if (failed > 0) process.exit(1);
152

