1	upstream fastapi_backend {
2	    # Option 1: TCP socket (default — matches uvicorn --host 0.0.0.0 --port 8000)
3	    server 127.0.0.1:8000;
4	
5	    # Option 2: Unix socket (uncomment and comment Option 1 for better performance)
6	    # server unix:/run/uvicorn/uvicorn.sock fail_timeout=0;
7	
8	    keepalive 32;
9	}
10	
11	# Rate limiting zone
12	limit_req_zone $binary_remote_addr zone=fastapi_limit:10m rate=30r/s;
13	
14	server {
15	    listen 80;
16	    server_name _;
17	
18	    # Security headers
19	    add_header X-Frame-Options "SAMEORIGIN" always;
20	    add_header X-Content-Type-Options "nosniff" always;
21	    add_header X-XSS-Protection "1; mode=block" always;
22	    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
23	
24	    # Gzip compression
25	    gzip on;
26	    gzip_types application/json text/plain text/css application/javascript text/xml application/xml image/svg+xml;
27	    gzip_min_length 256;
28	    gzip_vary on;
29	
30	    # Timeouts — async frameworks are fast, but long-polling/SSE may need headroom
31	    proxy_connect_timeout 10s;
32	    proxy_send_timeout    60s;
33	    proxy_read_timeout    120s;
34	    send_timeout          60s;
35	
36	    # Request size limit
37	    client_max_body_size 64M;
38	
39	    # Main application
40	    location / {
41	        proxy_pass http://fastapi_backend;
42	        limit_req zone=fastapi_limit burst=50 nodelay;
43	
44	        # Standard proxy headers
45	        proxy_set_header Host              $host;
46	        proxy_set_header X-Real-IP         $remote_addr;
47	        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
48	        proxy_set_header X-Forwarded-Proto $scheme;
49	        proxy_set_header X-Forwarded-Host  $host;
50	        proxy_set_header X-Forwarded-Port  $server_port;
51	        proxy_set_header Connection        "";
52	        proxy_http_version 1.1;
53	
54	        # Intercept upstream errors
55	        proxy_intercept_errors on;
56	    }
57	
58	    # WebSocket support (FastAPI natively supports ws://)
59	    location ~ ^/(ws|websocket)/ {
60	        proxy_pass http://fastapi_backend;
61	        proxy_http_version 1.1;
62	        proxy_set_header Upgrade    $http_upgrade;
63	        proxy_set_header Connection "upgrade";
64	        proxy_set_header Host              $host;
65	        proxy_set_header X-Real-IP         $remote_addr;
66	        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
67	        proxy_set_header X-Forwarded-Proto $scheme;
68	        proxy_read_timeout 86400s;
69	        proxy_send_timeout 86400s;
70	    }
71	
72	    # Health check endpoint (bypass rate limiting)
73	    location = /health {
74	        proxy_pass http://fastapi_backend;
75	        proxy_set_header Host $host;
76	        proxy_http_version 1.1;
77	        proxy_set_header Connection "";
78	        access_log off;
79	        limit_req off;
80	    }
81	
82	    # OpenAPI docs — serve through proxy but skip rate limiting
83	    location ~ ^/(docs|redoc|openapi\.json)$ {
84	        proxy_pass http://fastapi_backend;
85	        proxy_set_header Host $host;
86	        proxy_http_version 1.1;
87	        proxy_set_header Connection "";
88	        limit_req off;
89	    }
90	
91	    # Static files — serve directly by Nginx for performance
92	    location /static/ {
93	        alias /data/agent/choucisan/static/;
94	        expires 30d;
95	        add_header Cache-Control "public, immutable";
96	        access_log off;
97	    }
98	
99	    # Favicon
100	    location = /favicon.ico {
101	        alias /data/agent/choucisan/static/favicon.ico;
102	        access_log off;
103	        log_not_found off;
104	    }
105	
106	    # Deny access to hidden files and Python artifacts
107	    location ~ /\. {
108	        deny all;
109	        access_log off;
110	        log_not_found off;
111	    }
112	
113	    location ~ __pycache__ {
114	        deny all;
115	        access_log off;
116	        log_not_found off;
117	    }
118	
119	    # Custom error pages
120	    error_page 502 503 504 /50x.html;
121	    location = /50x.html {
122	        root /usr/share/nginx/html;
123	        internal;
124	    }
125	}
